users = list_users({})
days = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

# Fetch all (day, user) availability in parallel
busy_map = fold acc = {} for day in days {
    per_user = for u in users {
        a = boundary retry 3 {
            return get_availability({ user_id: u.id, date: day })
        } catch err {
            return fail("AVAIL_FAILED", u.id + " " + day + ": " + err.message)
        }
        return { key: day + "|" + u.id, busy: a.busy if a.busy != null else [] }
    }
    return fold m = acc for pu in per_user { return m + { [pu.key]: pu.busy } }
}

# to minutes since midnight
mins = { ["00"]: 0 }
hhmm_to_min = json.parse("\"unused\"")

# candidate starts: 09:00..16:00 on 30-min boundary (60-min meeting ending by 17:00)
starts = list.range(540, 961, 30)

to_min = json.parse("\"x\"")

# helper inline: parse "HH:MM" -> minutes; do with split+parse
candidates = for day in days {
    day_starts = for s in starts {
        e = s + 60
        ok_all = fold ok = true for u in users {
            busy = busy_map[day + "|" + u.id]
            ok_u = fold free = ok for b in busy {
                parts_b = text.split(b.start, ":")
                parts_e = text.split(b.end, ":")
                bs = number.parse(parts_b[0]) * 60 + number.parse(parts_b[1])
                be = number.parse(parts_e[0]) * 60 + number.parse(parts_e[1])
                overlap = bs < e and s < be
                return free and not overlap
            }
            return ok_u
        }
        skip if not ok_all
        return s
    }
    skip if day_starts == []
    first = day_starts[0]
    sh = text.slice("0" + text.replace(json.encode(number.floor(first / 60)), "\"", ""), 0, 2)
    return { day, start_min: first }
}

assert(candidates != [], "no slot found")
best = candidates[0]
fmt = for v in [best.start_min, best.start_min + 60] {
    h = number.floor(v / 60)
    m = v - h * 60
    hs = json.encode(h)
    ms = json.encode(m)
    h2 = ("0" + hs) if h < 10 else hs
    m2 = (ms + "0") if m < 10 else ms
    return h2 + ":" + m2 + ":00Z"
}
result = boundary { return submit_result({ answer: { start: best.day + "T" + fmt[0], end: best.day + "T" + fmt[1] } }) } catch err { return fail("SUBMIT_FAILED", err.message) }
return result
